	st.fmem.slots[4].confirm = u8(1)
	st.fmem.slots[4].priority = u8(128)
	st.sdeb_2 = fault.Debounce{
		fail_thr: 1
		pass_thr: 1
		jump: true
	}
	st.sdeb_3 = fault.Debounce{
		fail_thr: 1
		pass_thr: 1
		jump: true
	}
	st.sdeb_4 = fault.Debounce{
