		pass_thr: 1
		jump: true
	}
	st.fmem.n = 5
	st.fmem.cap = 1 // snapshot entries
	st.fmem.init()
	st.conn_diag.server.faults = st.fmem.uds_ops() // 0x19 / 0x14 / 0x85
	mut sched := loom.Scheduler{}
	sched.every(10_000, io_can0_10ms, &st)
	for {
		loom_t0 := osal.now_us()
		sched.run(loom_t0)
		loom_t1 := osal.now_us()
		sched.account(loom_t1 - loom_t0, loom_t1) // per-core load
		osal.sleep_us(1000)
	}
}

pub fn run(can0 can.Channel) {
	t_can0 := spawn partition_can0(can0)
	t_sense := spawn partition_sense(0, unsafe { nil })
	t_ctrl := spawn partition_ctrl(1, unsafe { nil })
	t_can0.wait()
	t_sense.wait()
	t_ctrl.wait()
}

// rx_status_of: what com.RxMonitor answered, as the signal status it publishes
fn rx_status_of(p com.RxPublish) sig.RxStatus {
	return match p {
		.none { .never_received }
		.ok { .ok }
		.timeout { .timeout }
		.integrity { .integrity }
	}
}
